#!/usr/bin/env node
// Regenerates src/data/ca-zip-places.js from migrations/012_ca_zip_places.sql,
// the same 2,593 California ZIPs as the Supabase table public.ca_zip_places.
// The API checks a residential lead's ZIP against this set (lead-contract.js).
// Run: node scripts/build-ca-zip-set.cjs   (then commit the regenerated file)
'use strict';
const fs = require('node:fs');
const path = require('node:path');

const root = path.join(__dirname, '..');
const sql = fs.readFileSync(path.join(root, 'migrations/012_ca_zip_places.sql'), 'utf8');
const zips = [...sql.matchAll(/^\s*\('(\d{5})',/gm)].map((m) => m[1]);
const unique = [...new Set(zips)].sort();
if (unique.length !== zips.length) throw new Error('duplicate ZIP rows in migration 012');
if (unique.length !== 2593) throw new Error(`expected 2593 ZIPs, found ${unique.length}`);

const lines = [];
for (let i = 0; i < unique.length; i += 12) lines.push('  ' + unique.slice(i, i + 12).map((z) => `'${z}'`).join(', ') + ',');
const out = `'use strict';
// GENERATED by scripts/build-ca-zip-set.cjs from migrations/012_ca_zip_places.sql.
// Do not edit by hand. ${unique.length} California ZIPs (GeoNames, CC BY 4.0), the
// same set as Supabase public.ca_zip_places.
module.exports = new Set([
${lines.join('\n')}
]);
`;
fs.writeFileSync(path.join(root, 'src/data/ca-zip-places.js'), out);
console.log(`wrote src/data/ca-zip-places.js (${unique.length} ZIPs)`);
